-- Insert into questions\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b1_mcq_1', 'mcq', 'Greetings', 1, '{"question":"What does નમસ્તે mean?","gujaratiText":"નમસ્તે","options":["Hello","Goodbye","Thanks","Sorry"],"answer":"Hello","answerGujarati":"નમસ્તે","explanation":"નમસ્તે is “hello”; a respectful greeting.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b1_mcq_2', 'mcq', 'Numbers', 1, '{"question":"How do you say the number 3 in Gujarati?","gujaratiText":"એક · બે · ત્રણ · ચાર","options":["એક","બે","ત્રણ","ચાર"],"answer":"ત્રણ","answerGujarati":"ત્રણ","explanation":"ત્રણ is three.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b1_mcq_3', 'mcq', 'Greetings', 1, '{"question":"What does કેમ છો mean?","gujaratiText":"કેમ છો","options":["How are you","Thank you","Good morning","Goodbye"],"answer":"How are you","answerGujarati":"કેમ છો","explanation":"Literally “how are you?” — કેમ छो?","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b1_pr_1', 'pronunciation', 'Pronunciation', 1, '{"question":"Say this word out loud","gujaratiText":"નમસ્તે","options":null,"answer":null,"answerGujarati":"નમસ્તે","explanation":"namaste — stress the second syllable lightly.","pronunciationTarget":"namaste"}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b1_mcq_4', 'mcq', 'Basics', 1, '{"question":"How do you say Yes in Gujarati?","gujaratiText":"હા · ના","options":["હા","ના","સારું","ઠીક"],"answer":"હા","answerGujarati":"હા","explanation":"હા means yes.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b2_mcq_1', 'mcq', 'Gender', 2, '{"question":"છોકરો (chhokro) means boy. What gender is it?","gujaratiText":"છોકરો","options":["Masculine","Feminine","Neuter","None"],"answer":"Masculine","answerGujarati":"છોકરો","explanation":"Masculine nouns often end in ઓ.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b2_mcq_2', 'mcq', 'Pronouns', 2, '{"question":"Which pronoun means ''I'' in Gujarati?","gujaratiText":"હું · તમે · તે","options":["તમે","તે","હું","અમે"],"answer":"હું","answerGujarati":"હું","explanation":"હું is first person singular.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b2_mcq_3', 'mcq', 'Gender', 2, '{"question":"છોકરી ends in -i. What gender is it?","gujaratiText":"છોકરી","options":["Feminine","Masculine","Neuter","Mixed"],"answer":"Feminine","answerGujarati":"છોકરી","explanation":"Many feminine nouns end in ઈ.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b2_pr_1', 'pronunciation', 'Pronouns', 2, '{"question":"Say this pronoun","gujaratiText":"હું","options":null,"answer":null,"answerGujarati":"હું","explanation":"hu — short “u” vowel.","pronunciationTarget":"hu"}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b2_mcq_4', 'mcq', 'Nouns', 2, '{"question":"What does ઘર mean and what gender is it?","gujaratiText":"ઘર","options":["House/Neuter","Boy/Masculine","Girl/Feminine","Water/Neuter"],"answer":"House/Neuter","answerGujarati":"ઘર (નપુંસક)","explanation":"ઘર is neuter house/home.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b3_mcq_1', 'mcq', 'Postpositions', 3, '{"question":"ઘરમાં means what?","gujaratiText":"ઘરમાં","options":["In the house","On the house","From the house","Near the house"],"answer":"In the house","answerGujarati":"ઘરમાં","explanation":"માં marks location “in/on inside”.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b3_mcq_2', 'mcq', 'Postpositions', 3, '{"question":"Which postposition means FROM in Gujarati?","gujaratiText":"માં · પર · થી · ને","options":["માં","પર","થી","ને"],"answer":"થી","answerGujarati":"થી","explanation":"થી conveys source/from.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b3_mcq_3', 'mcq', 'Verbs', 3, '{"question":"તે ડૉક્ટર છે means?","gujaratiText":"તે ડૉક્ટર છે","options":["He is a doctor","She was a doctor","He will be a doctor","I am a doctor"],"answer":"He is a doctor","answerGujarati":"તે ડૉક્ટર છે","explanation":"Present copula છે marks “is”.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b3_pr_1', 'pronunciation', 'Phrases', 3, '{"question":"Say this phrase","gujaratiText":"કેમ છો","options":null,"answer":null,"answerGujarati":"કેમ છો","explanation":"kem cho — how are you?","pronunciationTarget":"kem cho"}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b3_mcq_4', 'mcq', 'Tense', 3, '{"question":"What is the past tense of છે (is)?","gujaratiText":"છું · હતો","options":["હતો/હતી","હશે","ছું","હોય"],"answer":"હતો/હતી","answerGujarati":"હતો/હતી","explanation":"હતો and હતી are common past-tense patterns that agree with gendered subjects.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b4_mcq_1', 'mcq', 'Syntax', 4, '{"question":"Gujarati follows which word order?","gujaratiText":"વાક્યરચના","options":["SOV","SVO","VSO","OVS"],"answer":"SOV","answerGujarati":"SOV","explanation":"Subject–object–verb is the default scaffolding.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b4_mcq_2', 'mcq', 'Adjectives', 4, '{"question":"સારો છોકરો means good boy. How do you say good girl?","gujaratiText":"સારો છોકરો · સારી છોકરી","options":["સારી છોકરી","સારો છોકરી","સારું છોકરી","સારા છોકરી"],"answer":"સારી છોકરી","answerGujarati":"સારી છોકરી","explanation":"Adjective સારું agrees: સારી with feminine છોકરી.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b4_mcq_3', 'mcq', 'Translation', 4, '{"question":"Translate: I drink water","gujaratiText":"પાણી પીવું","options":["હું પાણી પીઉ છું","હું પાણી ખાઉ છું","તે પાણી પીવે છે","અમે પાણી પીઉ છું"],"answer":"હું પાણી પીઉ છું","answerGujarati":"હું પાણી પીઉ છું","explanation":"First person + present habitual પીઉ છું.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b4_pr_1', 'pronunciation', 'Sentence', 4, '{"question":"Say this sentence","gujaratiText":"હું ભૂખ્યો છું","options":null,"answer":null,"answerGujarati":"હું ભૂખ્યો છું","explanation":"hu bhukhyo chhu — I am hungry (masc speaker).","pronunciationTarget":"hu bhukhyo chhu"}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b4_mcq_4', 'mcq', 'Agreement', 4, '{"question":"મોટો means big (masc). What is big in neuter form?","gujaratiText":"મોટું","options":["મોટું","મોટી","મોટા","મોટે"],"answer":"મોટું","answerGujarati":"મોટું","explanation":"Neuter agreement uses મોટું.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b5_mcq_1', 'mcq', 'Inclusive we', 5, '{"question":"Translate: We are learning Gujarati (including listener)","gujaratiText":"આપણે · અમે","options":["આપણે ગુજરાતી શીખીએ છીએ","અમે ગુજરાતી શીખીએ છીએ","તેઓ ગુજરાતી શીખે છે","હું ગુજરાતી શીખું છું"],"answer":"આપણે ગુજરાતી શીખીએ છીએ","answerGujarati":"આપણે ગુજરાતી શીખીએ છીએ","explanation":"આપણે signals “we” that includes you, the listener.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b5_mcq_2', 'mcq', 'Pronouns', 5, '{"question":"What is the difference between અમે and આપણે?","gujaratiText":"અમે · આપણે","options":["અમે excludes listener આપણે includes listener","They mean the same thing","અમે is formal આપણે is informal","અમે is plural આપણે is singular"],"answer":"અમે excludes listener આપણે includes listener","answerGujarati":"અમે / આપણે","explanation":"અમે is exclusive we; આપણે is inclusive.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b5_mcq_3', 'mcq', 'Grammar', 5, '{"question":"નો ની નું are all forms of which postposition?","gujaratiText":"નો ની નું","options":["Possessive of","In","From","To"],"answer":"Possessive of","answerGujarati":"સંબંધ દર્શક","explanation":"These mark possession agreement with noun gender.","pronunciationTarget":null}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b5_pr_1', 'pronunciation', 'Fluency', 5, '{"question":"Say this full sentence","gujaratiText":"ભારત મારો દેશ છે","options":null,"answer":null,"answerGujarati":"ભારત મારો દેશ છે","explanation":"bharat maro desh chhe","pronunciationTarget":"bharat maro desh chhe"}');\nINSERT INTO public.questions (id, type, skill, band, content) VALUES ('b5_mcq_4', 'mcq', 'Reading', 5, '{"question":"તે પુસ્તક વાંચે છે translates to?","gujaratiText":"તે પુસ્તક વાંચે છે","options":["She reads a book","He ate a book","They will read","I read books"],"answer":"She reads a book","answerGujarati":"તે પુસ્તક વાંચે છે","explanation":"Present habitual reading fits this gloss.","pronunciationTarget":null}');\n\n\n-- Insert into placement_questions\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b1_1', 'mcq', 'Greetings', 1, '{"question":"What does નમસ્તે mean?","gujaratiText":"નમસ્તે","options":["Hello","Goodbye","Thanks","Sorry"],"answer":"Hello","answerGujarati":"નમસ્તે","explanation":"નમસ્તે is a common greeting meaning hello.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b1_2', 'pronunciation', 'Numbers', 1, '{"question":"Say this number word out loud.","gujaratiText":"ત્રણ","options":null,"answer":null,"answerGujarati":"ત્રણ","explanation":"Pronunciation guide: tran","pronunciationTarget":"tran"}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b2_1', 'mcq', 'Pronouns', 2, '{"question":"છોકરો (chhokro) means boy. What gender is it?","gujaratiText":"છોકરો","options":["Masculine","Feminine","Neuter","None"],"answer":"Masculine","answerGujarati":"છોકરો","explanation":"-o noun endings are typically masculine.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b2_2', 'mcq', 'Gender', 2, '{"question":"છોકરી ends in -i. What gender is it?","gujaratiText":"છોકરી","options":["Feminine","Masculine","Neuter","Mixed"],"answer":"Feminine","answerGujarati":"છોકરી","explanation":"-i endings often mark feminine nouns.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b3_1', 'mcq', 'Postpositions', 3, '{"question":"ઘરમાં means what?","gujaratiText":"ઘરમાં","options":["In the house","On the house","From the house","Near the house"],"answer":"In the house","answerGujarati":"ઘરમાં","explanation":"માં often means in or inside.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b3_2', 'pronunciation', 'Phrases', 3, '{"question":"Say this phrase clearly.","gujaratiText":"કેમ છો","options":null,"answer":null,"answerGujarati":"કેમ છો","explanation":"kem cho — how are you","pronunciationTarget":"kem cho"}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b4_1', 'mcq', 'Syntax', 4, '{"question":"Gujarati follows which word order?","gujaratiText":"હું જમી લઉ છું.","options":["SOV","SVO","VSO","OVS"],"answer":"SOV","answerGujarati":"SOV માળખું","explanation":"Subject–Object–Verb is typical in Gujarati.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b4_2', 'mcq', 'Adjectives', 4, '{"question":"મોટો means big (masc). What is big in neuter form?","gujaratiText":"મોટો / મોટું","options":["મોટું","મોટી","મોટા","મોટે"],"answer":"મોટું","answerGujarati":"મોટું","explanation":"Neuter adjectives commonly use મોટું.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b5_1', 'mcq', 'Inclusive pronouns', 5, '{"question":"What is the difference between અમે and આપણે?","gujaratiText":"અમે · આપણે","options":["અમે excludes listener આપણે includes listener","They mean the same thing","અમે is formal આપણે is informal","અમે is plural આપણે is singular"],"answer":"અમે excludes listener આપણે includes listener","answerGujarati":"અમે સાંભાળનારને બાકાત; આપણે સાથે સમાવે.","explanation":"અમે is “we” excluding the listener; આપણે includes the listener.","pronunciationTarget":null}');\nINSERT INTO public.placement_questions (id, type, skill, band, content) VALUES ('pl_b5_2', 'mcq', 'Reading', 5, '{"question":"તે પુસ્તક વાંચે છે translates to?","gujaratiText":"તે પુસ્તક વાંચે છે","options":["She reads a book","He ate a book","They will read","I read books"],"answer":"She reads a book","answerGujarati":"તે પુસ્તક વાંચે છે","explanation":"Context often clarifies gender; this is a present habitual reading sense.","pronunciationTarget":null}');\n